// Builds src/app/arms/arms-images.ts from the optimised heraldic SVGs in src/app/arms/images/.
// The images are inlined (not referenced) because the coat of arms is also exported as a stand-alone SVG/PNG.
// Run: node scripts/build-arms-images.mjs   (sources and licences: src/app/arms/images/README.md)
import { readdirSync, readFileSync, writeFileSync } from 'node:fs';

const dir = 'src/app/arms/images';
const out = [
  '// GENERATED by scripts/build-arms-images.mjs from src/app/arms/images/*.svg - do not edit.',
  '// Sources and licences: src/app/arms/images/README.md',
  'export interface ArmsImage { viewBox: string; body: string; }',
  '',
  'export const ARMS_IMAGES: Record<string, ArmsImage> = {',
];
for (const file of readdirSync(dir).filter(f => f.endsWith('.svg')).sort()) {
  const src = readFileSync(`${dir}/${file}`, 'utf8').trim();
  const root = src.match(/^<svg\b([^>]*)>/);
  const viewBox = root?.[1].match(/viewBox="([^"]+)"/)?.[1];
  if (!root || !viewBox || !src.endsWith('</svg>')) {
    throw new Error(`${file}: unexpected structure`);
  }
  const style = root[1].match(/\sstyle="([^"]*)"/)?.[1];
  let body = src.slice(root[0].length, -'</svg>'.length).replace(/xlink:href=/g, 'href=');
  if (style) {
    body = `<g style="${style}">${body}</g>`;
  }
  out.push(`  '${file.slice(0, -4)}': { viewBox: '${viewBox}', body: ${JSON.stringify(body)} },`);
}
out.push('};', '');
writeFileSync('src/app/arms/arms-images.ts', out.join('\n'));
console.log('arms-images.ts written');
